from pathlib import Path
import re,json,difflib
root=Path(__file__).resolve().parents[2]
changes=[]
def update(p, fn):
 old=p.read_text(); new=fn(old)
 if old!=new:
  p.write_text(new)
  changes.append({'file':str(p.relative_to(root)),'patch':''.join(difflib.unified_diff(old.splitlines(True),new.splitlines(True),fromfile=str(p.relative_to(root)),tofile=str(p.relative_to(root))))})
# These are current implementation pointers, not copied lab modules or old HTTP URLs.
names={p.name for p in (root/'source').glob('*.js')}
pat=re.compile(r'(?<![\w/-])src/([\w.-]+\.js)')
def pointers(s):
 return pat.sub(lambda m: 'source/'+m[1] if m[1] in names else m[0],s)
for p in [*root.glob('*.md'),*root.glob('docs/**/*.md')]:
 if p.name=='nginx-hosting.md':continue # distinguish historical cache evidence below
 update(p,pointers)
# Markdown link targets have ../src/ and need separate matched paths.
for p in [*root.glob('*.md'),*root.glob('docs/**/*.md')]:
 if p.name=='nginx-hosting.md':continue
 update(p,lambda s: re.sub(r'(?<=\.\./)src/([\w.-]+\.js)',lambda m:'source/'+m[1] if m[1] in names else m[0],s))
update(root/'README.md', lambda s:s.replace('| `src/` | Game systems, renderer, UI, audio, input and portable script interpreter. |','| `source/` | Editable game modules; input to bundling and focused tests, **not loaded directly by ordinary gameplay**. See [source instructions](source/README.md). |\n| `src/` | Generated `game.bundle.js`, debugging source map and runtime CSS. See [runtime files](src/README.md). |').replace('The editable modules remain available, and existing saves/profiles keep their original format and storage.','The editable modules are kept separately in `source/`; only the generated bundle runs during ordinary gameplay. Existing saves/profiles keep their original format and storage.'))
update(root/'docs/javascript-bundling.md',lambda s:s.replace('The editable game remains split into modules in `src/`. Before running or\npackaging it, the preparation tools combine the browser entry and Three.js into','The editable game modules are kept separately in [`source/`](../source/README.md).\nThey are **not loaded directly by ordinary gameplay**. Before launching from the\ncheckout or packaging it, the preparation tools read those modules and combine\nthe browser entry and Three.js into').replace('The first current-source bundle combines','The initial 26 October bundle combined').replace('Copy the matching\n`index.html` and complete `src/` directory together, including `game.bundle.js`\nand `game.bundle.js.map`; retain the other existing deployment directories.\nThe bundle is generated output: edit the original modules, not this file.','Copy the matching\n`index.html` and complete runtime `src/` directory together, including\n`game.bundle.js`, `game.bundle.js.map` and CSS; retain the other existing\ndeployment directories. The separate `source/` directory is needed to edit,\ntest or regenerate the bundle, but is excluded from normal desktop/Android\npackages and is not needed on a static webhost. The bundle is generated output:\nedit `source/`, not `src/game.bundle.js`.\n\n`npm start` and `npm run serve` read `source/` during their automatic preparation\nstep. That development step is distinct from running the prepared game: the\nbrowser/WebView/Electron renderer executes the resulting bundle. Tests and\nexplicit debugging imports may load individual modules deliberately.\nThe independent `RC_ACTOR_TEST`, `RC_COIN_TEST` and `RC_SHOVE_TEST` laboratories\nkeep their own source layouts and do not use the main runtime bundle.').replace('- Source modules remain revisioned in the import map for tools and debugging;','- `source/` modules remain revisioned in the import map for tools and debugging;'))
update(root/'docs/building.md',lambda s:s.replace('`package-lock.json`, `src/`, `electron/`','`package-lock.json`, `source/`, `src/`, `electron/`').replace('These commands run the source without generating packages.','These commands regenerate `src/game.bundle.js` from the editable modules in\n`source/`, then run that bundle without generating packages. The individual\nmodules are not loaded directly by ordinary gameplay. Keep `source/` in a\ndevelopment checkout; generated runtime distributions do not need it.').replace('An existing `dist/`\npackage still contains the source and metadata from when it was generated:\nchanging the Over dialog to **1.0.1** does not update a previously built **1.0.0**\npackage. Record the executable/package version, source revision or file hashes,\nplatform, inputs and checks for each release run. Source tests and older-package\nchecks do not certify a new 1.0.1 release, and Linux browser/Electron checks\ndo not certify Windows, macOS or ARM hardware.','An existing `dist/`\npackage still contains the prepared runtime and metadata from when it was\ngenerated; editing the source or changing the Over version does not update it.\nRecord the executable/package version, source revision or file hashes, platform,\ninputs and checks for each release run. Source tests and older-package checks\ndo not certify a newly generated release, and Linux browser/Electron checks\ndo not certify Windows, macOS or ARM hardware.'))
update(root/'ANDROID.md',lambda s:s.replace('bundles the current port source and original runtime assets','bundles the prepared game runtime and original assets').replace('    ├── src/\n','    ├── src/                    # Generated bundle, source map and runtime CSS\n').replace('It does not include Electron, development dependencies other than Three.js, tests, original executables, the ISO or `temp_work/`.','It does not include the editable `source/` modules, Electron, development dependencies other than Three.js, tests, original executables, the ISO or `temp_work/`. Preparation first reads `source/` to regenerate the bundle; the installed app runs `src/game.bundle.js` without individual module requests.').replace('Do not edit staged files. Edit the shared source/assets instead.','Do not edit staged files or the generated bundle. Edit the shared `source/` modules or assets instead.'))
update(root/'docs/nginx-hosting.md',lambda s:s.replace('Upload its prepared source,','Upload its prepared runtime,').replace('├── src/\n','├── src/                     # game.bundle.js, source map and runtime CSS\n',1).replace('180 MB of disk space.','200 MB of disk space; measure the staged directory for the current total.').replace('tree does not need the rest of `node_modules`, `electron/`, development tools,','tree does not need the editable `source/` directory, the rest of `node_modules`,\n`electron/`, development tools,').replace('https://games.nostalgiarealm.com/redcatspookkasteel/src/main.js','https://games.nostalgiarealm.com/redcatspookkasteel/src/game.bundle.js').replace('https://games.nostalgiarealm.com/redcatspookkasteel/src/actor-render-residency.js','https://games.nostalgiarealm.com/redcatspookkasteel/src/game.bundle.js').replace('The individual import-map entries remain\navailable for debugging and tools; users do not need to clear their cache or','The individual import-map entries now point into `source/`, which is needed\nonly in development checkouts for debugging and tools. A deployed site does\nnot need that folder. Users do not need to clear their cache or'))
update(root/'docs/portability.md',lambda s:s.replace('The core is ES modules and typed arrays.','The editable core in `source/` uses ES modules and typed arrays. Preparation\ncombines it with Three.js into `src/game.bundle.js`; ordinary desktop, browser\nand Android gameplay runs that bundle without loading individual modules.'))
# Preserve a literal recorded source-manifest filename from the old campaign.
update(root/'docs/campaign-validation-2026-10-18.md',lambda s:s.replace('manifest and identifies `source/audio.js`','manifest and identifies historical `src/audio.js` (now `source/audio.js`)'))
update(root/'temp_work/README.md',lambda s:s.replace('## Repository copies','## Historical paths and findings\n\nThese records describe the checkout and test run at the date they were written.\nThey are evidence, not current setup instructions or an outstanding-task list.\nThe main game\'s editable modules moved from `src/` to `source/` on 26 October\n2026; old module paths, source manifests and source hashes in retained records\nrefer to that earlier layout and are deliberately preserved. The new `src/`\ncontains the generated runtime bundle, source map and CSS. Standalone labs\nretain their independent `src/` trees. Use [the main README](../README.md),\n[build guide](../docs/building.md), [bundling guide](../docs/javascript-bundling.md)\nand [current implementation audit](../docs/native-parity-audit.md) for current\nworkflow and status. Retained upstream/license documents keep their original\nwording and provenance.\n\n## Repository copies'))
(root/'temp_work/source-layout-2026-10-26/documentation-updates.json').write_text(json.dumps({'changes':[{k:v for k,v in c.items() if k!='patch'} for c in changes]},indent=2)+'\n')
(root/'temp_work/source-layout-2026-10-26/documentation-updates.patch').write_text(''.join(c['patch'] for c in changes))
print('edits',len(changes),'files',len({c['file'] for c in changes}))
